let current: Promise<void> | undefined;

function search(query: string, render: (items: string[]) => void) {
  current = fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then((r) => r.json() as Promise<string[]>)
    .then(render);
  return current;
}

type Settings = {
  currency?: string;
  freeShippingThreshold?: number;
  discountRate?: number;
  features?: { giftWrap?: boolean };
};

function resolveSettings(input: Settings) {
  return {
    currency: input.currency || 'USD',
    freeShippingThreshold: input.freeShippingThreshold || 50,
    discountRate: input.discountRate || 0.1,
    giftWrap: input.features?.giftWrap || false,
  };
}

console.log(resolveSettings({
  currency: 'ARS',
  freeShippingThreshold: 0,   // free shipping on every order
  discountRate: 0,            // launch week: no discount
  features: { giftWrap: false },
}));
